/**
 * GitLaTeX live collaboration relay.
 *
 * One Durable Object per room holds the shared Yjs document of a project and
 * relays edits and cursors between everyone connected to it. It never sees
 * the Git repository: each collaborator saves, commits and compiles on their
 * own machine.
 *
 * Two kinds of token:
 *   - ADMIN_TOKEN (a Worker secret, chosen when deploying) belongs to the
 *     owner. It manages rooms through /admin and can join any room.
 *   - Each room has its own token, generated by the relay when the owner
 *     creates the room. The owner shares it with that project's co-authors.
 *
 *   wss://<worker>/parties/collab/<room>?token=…        Yjs sync + awareness
 *   GET    /parties/collab/<room>?token=…               { room, files, peers }
 *   GET    /admin/rooms                                 list rooms        (Bearer ADMIN_TOKEN)
 *   POST   /admin/rooms/<room>                          create (or fetch) a room
 *   POST   /admin/rooms/<room>/token                    issue a new room token
 *   DELETE /admin/rooms/<room>                          delete a room and its document
 *
 * The document has one root map, `files`: path → Y.Text.
 */
import { DurableObject } from 'cloudflare:workers';
import { routePartykitRequest } from 'partyserver';
import { YServer } from 'y-partyserver';
import * as Y from 'yjs';

export interface Env {
  Collab: DurableObjectNamespace<Collab>;
  Registry: DurableObjectNamespace<Registry>;
  /** The owner's secret, chosen when deploying (`wrangler secret put ADMIN_TOKEN`). */
  ADMIN_TOKEN: string;
}

export interface RoomRecord {
  room: string;
  token: string;
  createdAt: string;
}

/** Room names go into URLs; GitLaTeX derives them from the project name. */
const ROOM = /^[a-z0-9._-]{1,64}$/;

/** Durable Object storage values are capped, so the document is stored in chunks. */
const CHUNK = 512 * 1024;

export class Collab extends YServer<Env> {
  static options = { hibernate: true };
  static callbackOptions = { debounceWait: 2000, debounceMaxWait: 10000 };

  async onLoad() {
    const count = await this.ctx.storage.get<number>('doc:chunks');
    if (!count) return;
    const keys = Array.from({ length: count }, (_, i) => `doc:${i}`);
    const parts = await this.ctx.storage.get<Uint8Array>(keys);
    const total = keys.reduce((n, k) => n + (parts.get(k)?.length ?? 0), 0);
    const update = new Uint8Array(total);
    let at = 0;
    for (const k of keys) {
      const part = parts.get(k);
      if (!part) return; // incomplete write: start empty rather than corrupt
      update.set(part, at);
      at += part.length;
    }
    Y.applyUpdate(this.document, update);
  }

  async onSave() {
    const update = Y.encodeStateAsUpdate(this.document);
    const entries: Record<string, Uint8Array | number> = {};
    let count = 0;
    for (let at = 0; at < update.length; at += CHUNK) entries[`doc:${count++}`] = update.slice(at, at + CHUNK);
    entries['doc:chunks'] = count;
    const old = (await this.ctx.storage.get<number>('doc:chunks')) ?? 0;
    await this.ctx.storage.put(entries);
    if (old > count) await this.ctx.storage.delete(Array.from({ length: old - count }, (_, i) => `doc:${count + i}`));
  }

  /** Plain HTTP: what is in the room (handy for checking a deployment). */
  async onRequest(): Promise<Response> {
    const files = [...this.document.getMap<Y.Text>('files').entries()].map(([path, text]) => ({ path, length: text.length }));
    const peers = [...this.document.awareness.getStates().values()]
      .map((s) => (s as { user?: { name?: string } }).user?.name)
      .filter(Boolean);
    return Response.json({ room: this.name, files: files.sort((a, b) => a.path.localeCompare(b.path)), peers });
  }

  /** Disconnect everyone (after the room's token changed). Clients retry and are refused. */
  async disconnectAll(reason: string) {
    for (const conn of this.getConnections()) conn.close(4001, reason);
  }

  /** Forget the room's document entirely (the room was deleted). */
  async wipe() {
    await this.disconnectAll('Room deleted');
    const files = this.document.getMap('files');
    this.document.transact(() => {
      for (const key of [...files.keys()]) files.delete(key);
    });
    await this.ctx.storage.deleteAll();
  }
}

/** The rooms and their tokens: one instance, addressed as "registry". */
export class Registry extends DurableObject<Env> {
  private key = (room: string) => `room:${room}`;

  async check(room: string, token: string): Promise<boolean> {
    const rec = await this.ctx.storage.get<RoomRecord>(this.key(room));
    return !!rec && sameSecret(token, rec.token);
  }

  async list(): Promise<RoomRecord[]> {
    const all = await this.ctx.storage.list<RoomRecord>({ prefix: 'room:' });
    return [...all.values()].sort((a, b) => a.room.localeCompare(b.room));
  }

  /** The room, created with a fresh token if it does not exist yet. */
  async ensure(room: string): Promise<RoomRecord & { created: boolean }> {
    const rec = await this.ctx.storage.get<RoomRecord>(this.key(room));
    if (rec) return { ...rec, created: false };
    const fresh = { room, token: newToken(), createdAt: new Date().toISOString() };
    await this.ctx.storage.put(this.key(room), fresh);
    return { ...fresh, created: true };
  }

  async rotate(room: string): Promise<RoomRecord | null> {
    const rec = await this.ctx.storage.get<RoomRecord>(this.key(room));
    if (!rec) return null;
    const next = { ...rec, token: newToken() };
    await this.ctx.storage.put(this.key(room), next);
    return next;
  }

  async remove(room: string): Promise<boolean> {
    return this.ctx.storage.delete(this.key(room));
  }
}

// ---------------------------------------------------------------------------

/** 24 random bytes, base64url: 32 characters. */
function newToken() {
  const bytes = crypto.getRandomValues(new Uint8Array(24));
  return btoa(String.fromCharCode(...bytes)).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}

/** Length-independent comparison. */
function sameSecret(given: string, expected: string | undefined) {
  if (!expected) return false;
  const a = new TextEncoder().encode(given);
  const b = new TextEncoder().encode(expected);
  let diff = a.length ^ b.length;
  for (let i = 0; i < Math.max(a.length, b.length); i++) diff |= (a[i] ?? 0) ^ (b[i] ?? 0);
  return diff === 0;
}

const registry = (env: Env) => env.Registry.getByName('registry');

const CORS = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Methods': 'GET, POST, DELETE, OPTIONS',
  'Access-Control-Allow-Headers': 'Authorization, Content-Type',
  'Access-Control-Max-Age': '86400',
};

const json = (body: unknown, status = 200) => Response.json(body, { status, headers: CORS });
const text = (body: string, status: number) => new Response(body, { status, headers: CORS });

async function admin(req: Request, env: Env, url: URL): Promise<Response> {
  if (!env.ADMIN_TOKEN) return json({ error: 'This relay has no ADMIN_TOKEN set.' }, 500);
  const given = (req.headers.get('Authorization') ?? '').replace(/^Bearer\s+/i, '');
  if (!sameSecret(given, env.ADMIN_TOKEN)) return json({ error: 'Wrong admin token.' }, 401);

  let parts: string[];
  try {
    parts = url.pathname.split('/').filter(Boolean).map(decodeURIComponent);
  } catch {
    return json({ error: 'Not found.' }, 404);
  }
  const [, section, room, action, ...rest] = parts;
  if (section !== 'rooms' || rest.length) return json({ error: 'Not found.' }, 404);
  const reg = registry(env);

  if (!room) {
    if (req.method === 'GET') return json({ rooms: await reg.list() });
    return json({ error: 'Method not allowed.' }, 405);
  }
  if (!ROOM.test(room)) return json({ error: 'Room names use a-z, 0-9, ".", "_" and "-" (up to 64).' }, 400);

  if (!action && req.method === 'POST') return json(await reg.ensure(room));
  if (action === 'token' && req.method === 'POST') {
    const rec = await reg.rotate(room);
    if (!rec) return json({ error: 'No such room.' }, 404);
    await env.Collab.getByName(room).disconnectAll('Room token changed');
    return json(rec);
  }
  if (!action && req.method === 'DELETE') {
    if (!(await reg.remove(room))) return json({ error: 'No such room.' }, 404);
    await env.Collab.getByName(room).wipe();
    return json({ deleted: room });
  }
  return json({ error: 'Method not allowed.' }, 405);
}

export default {
  async fetch(req: Request, env: Env): Promise<Response> {
    const url = new URL(req.url);
    if (req.method === 'OPTIONS') return new Response(null, { status: 204, headers: CORS });
    if (url.pathname === '/admin' || url.pathname.startsWith('/admin/')) return admin(req, env, url);

    // Only rooms are reachable; the Registry is never routed to directly.
    const m = /^\/parties\/collab\/([a-z0-9._-]{1,64})\/?$/.exec(url.pathname);
    if (!m) return text('GitLaTeX collaboration relay', 404);
    const room = m[1];

    const token = url.searchParams.get('token') ?? '';
    const allowed = sameSecret(token, env.ADMIN_TOKEN) || (await registry(env).check(room, token));
    if (!allowed) return text('Unauthorized', 401);

    const res = await routePartykitRequest(req, env as unknown as Record<string, unknown>, { cors: true });
    return res ?? text('Not found', 404);
  },
} satisfies ExportedHandler<Env>;
